import React, { useState } from 'react';
import Navbar from '../components/Navbar';
import ChatBot from '../components/ChatBot';

function Chat() {
  return (
    <div style={styles.container}>
      <Navbar />
      
      <div style={styles.content}>
        <div style={styles.header}>
          <h1 style={styles.title}>💬 AI Support Chat</h1>
          <p style={styles.subtitle}>Your personal AI companion, here to listen and support you</p>
        </div>

        <ChatBot />
      </div>
    </div>
  );
}

const styles = {
  container: {
    minHeight: '100vh',
    background: '#f5f7fa',
  },
  content: {
    maxWidth: '800px',
    margin: '0 auto',
    padding: '20px',
    paddingTop: '80px',
  },
  header: {
    textAlign: 'center',
    marginBottom: '30px',
  },
  title: {
    fontSize: '32px',
    color: '#333',
  },
  subtitle: {
    color: '#666',
    marginTop: '5px',
  },
};

export default Chat;
